"""Test del ciclo completo in una cartella temporanea: init, task (con le regole), piano, handoff, hook, esportazione. Non tocca nessun progetto."""
import json, os, subprocess, sys, tempfile
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent; F = str(ROOT / "factory.py")
ok = ko = 0
def v(nome, cond, det=""):
    global ok, ko
    if cond: ok += 1; print("  ok  " + nome)
    else: ko += 1; print("  KO  %s %s" % (nome, det))
d = Path(tempfile.mkdtemp()); env = {k: x for k, x in os.environ.items() if k not in ("FACTORY_ROOT", "FACTORY_PIANO")}; env["PLANCIA_HOME"] = str(d / "_casa")
def run(*a, stdin=None): return subprocess.run([sys.executable, F, *a], capture_output=True, text=True, encoding="utf-8", errors="replace", cwd=d, env=env, input=stdin)
(d / "passi.json").write_text(json.dumps({"task": "T", "steps": [{"id": "A", "testo": "uno"}, {"id": "B", "testo": "due", "dipende_da": ["A"]}]}))
x = run("init", "--modo", "governata"); v("init senza --scrivi non scrive nulla", x.returncode == 0 and not (d / ".factory").exists() and not (d / "AGENTS.md").exists())
x = run("init", "--modo", "governata", "--scrivi"); v("init --scrivi: .factory, regola, hook Claude e Copilot", (d / ".factory").is_dir() and "plancia:inizio" in (d / "AGENTS.md").read_text() and (d / ".claude/settings.json").exists() and (d / ".github/hooks/plancia.json").exists())
x = run("init", "--modo", "governata", "--scrivi"); v("init e ripetibile (nessun doppione)", (d / "AGENTS.md").read_text().count("plancia:inizio") == 1 and len(json.loads((d / ".claude/settings.json").read_text())["hooks"]["Stop"]) == 1)
x = run("task", "apri", "T1", "prova", "--da", "passi.json"); v("task apri crea il piano in DRAFT", x.returncode == 0 and "DRAFT" in x.stdout)
x = run("task", "apri", "../x"); v("id task con percorso rifiutato", x.returncode != 0)
x = run("task", "avvia", "T1"); v("avvia prima della conferma rifiutato", x.returncode == 2)
x = run("task", "conferma", "T1"); v("conferma senza frase rifiutata", x.returncode == 2)
x = run("task", "conferma", "T1", "ok procedi"); v("conferma con la frase della persona", x.returncode == 0)
x = run("task", "avvia", "T1"); v("avvia dopo la conferma", x.returncode == 0)
x = run("task", "eseguito", "T1"); v("eseguito rifiutato con passi aperti", x.returncode == 2 and "A" in x.stdout)
for p in ("A", "B"): run("piano", "passo", p, "fatto", "ok")
x = run("piano", "passo", "A", "in_corso"); v("passo FATTO non si riapre senza regressione", x.returncode == 2)
x = run("piano", "valida", "--json"); r = json.loads(x.stdout); v("valida: piano valido e chiudibile", r["valido"] and r["chiudibile"])
x = run("piano", "evento", "aggiungi un controllo", "--tipo", "subtask", "--passo", "B", "--applica"); v("evento subtask: B.1 senza rinumerare", "B.1" in x.stdout)
x = run("task", "eseguito", "T1"); v("eseguito rifiutato col nuovo sottopasso", x.returncode == 2)
run("piano", "passo", "B.1", "fatto"); x = run("task", "eseguito", "T1"); v("eseguito ammesso a piano completo", x.returncode == 0)
x = run("task", "verifica", "T1"); v("VERIFICATO senza persona rifiutato", x.returncode == 2)
x = run("task", "verifica", "T1", "--utente", "Anna"); v("VERIFICATO con la persona", x.returncode == 0)
x = run("task", "chiudi", "T1", "abbandonato"); v("task chiuso non si riapre", x.returncode == 2)
x = run("handoff"); v("handoff scrive STATE.md", x.returncode == 0 and (d / ".factory/STATE.md").exists())
x = run("hook", "PostToolUse", stdin=json.dumps({"hook_event_name": "PostToolUse", "cwd": str(d), "tool_name": "Bash", "prompt": "password=segreto"}))
ev = (d / ".factory/eventi.jsonl").read_text(); v("hook: evento scritto, nessun testo del prompt, exit 0", x.returncode == 0 and "hook:PostToolUse" in ev and "segreto" not in ev)
x = run("hook", "UserPromptSubmit", stdin=json.dumps({"hook_event_name": "UserPromptSubmit", "cwd": str(d)})); v("hook UserPromptSubmit: promemoria del piano come contesto per Claude Code", x.returncode == 0 and "additionalContext" in x.stdout and "[Plancia]" in x.stdout)
x = run("hook", "x", stdin="non json"); v("hook con input rotto: exit 0 e silenzio", x.returncode == 0 and not x.stdout and not x.stderr)
x = run("pannello", "--esporta", str(d / "p.html")); h = (d / "p.html").read_text(encoding="utf-8"); v("esporta: HTML autonomo con i dati", x.returncode == 0 and "SNAPSHOT" in h and "Analisi" not in h and "T1" in h)
x = run("pannello", "--host", "0.0.0.0"); v(  # noqa: S104 - prova che senza token e rifiutato
  "in rete senza token rifiutato", x.returncode == 2)
x = run("salute"); v("salute risponde", x.returncode in (0, 1) and "Salute:" in x.stdout)
print("\n%d ok, %d KO" % (ok, ko)); sys.exit(1 if ko else 0)
